window.PlanExport=(()=>{
 let busy=false,lastOptions=null;
 const dialog=()=>document.querySelector('#plan-export-dialog');
 const esc=x=>escapeHTML(x);
 function ready(){const s=Prep.stats();return Prep.isLoaded()&&s.total>0&&s.done===s.total&&!!Prep.getSettings().startLocal}
 function open(){if(!Prep.canConfigure())return;const settings=Prep.getSettings(),st=Prep.stats();const selected=lastOptions?.groups||window.PREP_NAV.filter(g=>!g.onsite||settings.deliveryMode!=='online').map(g=>g.id);dialog().innerHTML='<div class="export-dialog-head"><div><span class="kicker">把筹备变成一份执行文件</span><h2 id="export-heading">生成方案</h2></div><button class="export-close" data-export-close aria-label="关闭导出">×</button></div><p class="export-state '+(ready()?'is-ready':'')+'">'+(ready()?'全部适用待办已完成 · 可生成完整方案':'当前 '+st.done+'/'+st.total+' 项已完成 · 将生成筹备草稿'+(!settings.startLocal?'（请先设置开赛时间）':''))+'</p><p class="caption">文档使用当前页面参数。未完成项会列入草稿；生成文件不会自动勾选待办，也不等于已发布赛规。</p><label class="export-name">活动或方案名称<input data-export-name maxlength="80" value="'+esc(lastOptions?.title||'黑客松筹备方案')+'"></label><fieldset class="export-fieldset"><legend>选择本次文件包含的模块</legend><div class="export-modules">'+window.PREP_NAV.map(g=>'<label><input type="checkbox" data-export-group="'+g.id+'" '+(selected.includes(g.id)?'checked':'')+'><span>'+g.title+(g.onsite&&settings.deliveryMode==='online'?'<small>线上模式下仅作参考</small>':'')+'</span></label>').join('')+'</div></fieldset><div class="export-includes"><label><input type="checkbox" data-export-details '+(lastOptions?.details===false?'':'checked')+'>包含所选模块的执行细则</label><label><input type="checkbox" data-export-templates '+(lastOptions?.templates?'checked':'')+'>附报名、评分等表单模板（需选择赛制规划）</label></div><div class="export-preview"><strong>文件内容</strong><p>活动概况 → 时间表 → 所选模块与待办 → 待落实事项。赛制模块另含当前评分比例、人力和路演时长。</p><small>赛道、奖项、平台、合作方等未填写信息保留为建议或待补充，不会自动编造。</small></div><p data-export-status class="export-feedback" role="status" aria-live="polite"></p><div class="export-actions"><button class="btn secondary" data-export-format="docx">下载 Word <small>.docx</small></button><button class="btn" data-export-format="pdf">下载 PDF <small>.pdf</small></button></div><p class="caption export-private">文件在你的浏览器中生成，不上传文件内容。首次 PDF 导出需加载中文字体，请稍候。</p>';dialog().showModal()}
 async function download(format){if(busy)return;const status=dialog().querySelector('[data-export-status]');const options={title:dialog().querySelector('[data-export-name]').value,groups:[...dialog().querySelectorAll('[data-export-group]:checked')].map(el=>el.dataset.exportGroup),details:dialog().querySelector('[data-export-details]').checked,templates:dialog().querySelector('[data-export-templates]').checked};
  try{if(!options.groups.length)throw Error('请至少选择一个模块');busy=true;dialog().querySelectorAll('button,input').forEach(el=>el.disabled=true);status.textContent='正在整理方案并生成文件…';if(Prep.isLoaded())await Promise.race([Prep.flush(),new Promise((_,reject)=>setTimeout(()=>reject(Error('计划保存超时，请稍后重试导出')),15000))]);const model=PlanDocument.build({settings:Prep.getSettings(),config:{...planConfig},accountLoaded:Prep.isLoaded(),generatedAt:Date.now()},options);lastOptions=options;const blob=await PlanFiles.generate(model,format);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=model.filename+'.'+format;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='已生成'+model.status+'，下载已开始。';}
  catch(e){status.textContent=e.message||'生成失败，请重试';}finally{busy=false;dialog().querySelectorAll('button,input').forEach(el=>el.disabled=false)}
 }
 document.addEventListener('click',e=>{if(e.target.closest('[data-generate-plan]'))open();if(e.target.closest('[data-export-close]')&&!busy)dialog().close();const b=e.target.closest('[data-export-format]');if(b)download(b.dataset.exportFormat)});
 document.querySelector('#plan-export-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
 return {open,ready};
})();
